using System;
using System.Collections.Concurrent;
using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace DistributedCache.Client
{
    public sealed class CacheCredential
    {
        public string Username { get; }
        public byte[] AuthToken { get; }
        public DateTime IssuedAt { get; }
        public string Realm { get; }

        public CacheCredential(string username, byte[] authToken, string realm)
        {
            Username = username;
            AuthToken = authToken;
            IssuedAt = DateTime.UtcNow;
            Realm = realm;
        }

        public bool IsExpired(TimeSpan maxAge)
        {
            return (DateTime.UtcNow - IssuedAt) > maxAge;
        }
    }

    public sealed class ConnectionPool
    {
        private readonly ConcurrentQueue<PooledConnection> _available;
        private readonly ConcurrentDictionary<int, PooledConnection> _active;
        private readonly SemaphoreSlim _poolSemaphore;
        private readonly int _maxSize;
        private readonly string _endpoint;
        private int _totalCreated;

        public ConnectionPool(string endpoint, int maxSize = 16)
        {
            _endpoint = endpoint;
            _maxSize = maxSize;
            _available = new ConcurrentQueue<PooledConnection>();
            _active = new ConcurrentDictionary<int, PooledConnection>();
            _poolSemaphore = new SemaphoreSlim(maxSize, maxSize);
        }

        public async Task<PooledConnection> AcquireAsync(CacheCredential credential, CancellationToken ct)
        {
            await _poolSemaphore.WaitAsync(ct);

            if (_available.TryDequeue(out var conn))
            {
                if (conn.IsHealthy && !conn.Credential.IsExpired(TimeSpan.FromMinutes(30)))
                {
                    // Reuse connection - rebind credential context
                    conn.RebindCredential(credential);
                    if (!conn.IsHealthy)
                    {
                        // Rebind failed - must create fresh authenticated connection
                        conn.Dispose();
                        var freshConn = await CreateAuthenticatedConnectionAsync(credential, ct);
                        _active[freshConn.Id] = freshConn;
                        return freshConn;
                    }
                    _active[conn.Id] = conn;
                    return conn;
                }
                conn.Dispose();
            }

            var newConn = await CreateAuthenticatedConnectionAsync(credential, ct);
            _active[newConn.Id] = newConn;
            return newConn;
        }

        public void Release(PooledConnection conn)
        {
            _active.TryRemove(conn.Id, out _);
            _available.Enqueue(conn);
            _poolSemaphore.Release();
        }

        private async Task<PooledConnection> CreateAuthenticatedConnectionAsync(
            CacheCredential credential, CancellationToken ct)
        {
            var id = Interlocked.Increment(ref _totalCreated);
            var conn = new PooledConnection(id, _endpoint, credential);
            await conn.AuthenticateAsync(ct);
            return conn;
        }
    }

    public sealed class PooledConnection : IDisposable
    {
        public int Id { get; }
        public bool IsHealthy { get; private set; }
        public CacheCredential Credential { get; private set; }

        private readonly string _endpoint;
        private byte[] _sessionKey;
        private bool _disposed;

        public PooledConnection(int id, string endpoint, CacheCredential credential)
        {
            Id = id;
            _endpoint = endpoint;
            Credential = credential;
            IsHealthy = false;
        }

        public async Task AuthenticateAsync(CancellationToken ct)
        {
            // Simulate SASL-like authentication handshake
            var challenge = await SendAuthInitAsync(Credential.Username, Credential.Realm, ct);
            var response = ComputeAuthResponse(challenge, Credential.AuthToken);
            var result = await SendAuthResponseAsync(response, ct);

            if (result.Success)
            {
                _sessionKey = result.SessionKey;
                IsHealthy = true;
            }
            else
            {
                throw new AuthenticationException($"Cache auth failed for {Credential.Username}");
            }
        }

        public void RebindCredential(CacheCredential newCredential)
        {
            // Critical: When rebinding, we validate the new credential
            // belongs to the same security context as the existing session
            if (ValidateCredentialAffinity(newCredential))
            {
                Credential = newCredential;
                // Session key remains from original auth - same user, refreshed token
            }
            else
            {
                // Different user context - mark unhealthy to force re-auth
                IsHealthy = false;
                Credential = newCredential;
            }
        }

        private bool ValidateCredentialAffinity(CacheCredential newCredential)
        {
            // Check if credentials belong to the same authenticated user
            if (newCredential.Realm != Credential.Realm)
                return false;

            // Verify same user identity - username must match exactly
            if (!string.Equals(newCredential.Username, Credential.Username, StringComparison.Ordinal))
                return false;

            // Verify token derivation - tokens from same user session
            // share first 8 bytes as session prefix
            return CompareTokenPrefix(newCredential.AuthToken, Credential.AuthToken, 8);
        }

        private static bool CompareTokenPrefix(byte[] a, byte[] b, int length)
        {
            if (a == null || b == null) return false;
            if (a.Length < length || b.Length < length) return false;

            int result = 0;
            for (int i = 0; i < length; i++)
            {
                result |= a[i] ^ b[i];
            }
            return result == 0;
        }

        private Task<byte[]> SendAuthInitAsync(string username, string realm, CancellationToken ct)
        {
            // Simulated network call - returns server challenge
            var challenge = new byte[32];
            using (var rng = RandomNumberGenerator.Create())
                rng.GetBytes(challenge);
            return Task.FromResult(challenge);
        }

        private byte[] ComputeAuthResponse(byte[] challenge, byte[] token)
        {
            using (var hmac = new HMACSHA256(token))
            {
                return hmac.ComputeHash(challenge);
            }
        }

        private Task<AuthResult> SendAuthResponseAsync(byte[] response, CancellationToken ct)
        {
            // Simulated - in production this validates with the cache server
            byte[] sessionKey;
            using (var sha = SHA256.Create())
            {
                sessionKey = sha.ComputeHash(response);
            }
            return Task.FromResult(new AuthResult
            {
                Success = true,
                SessionKey = sessionKey
            });
        }

        public void Dispose()
        {
            if (!_disposed)
            {
                _disposed = true;
                IsHealthy = false;
                if (_sessionKey != null)
                    Array.Clear(_sessionKey, 0, _sessionKey.Length);
            }
        }
    }

    public class AuthResult
    {
        public bool Success { get; set; }
        public byte[] SessionKey { get; set; }
    }

    public class AuthenticationException : Exception
    {
        public AuthenticationException(string message) : base(message) { }
    }

    public class CacheClient
    {
        private readonly ConnectionPool _pool;

        public CacheClient(string endpoint)
        {
            _pool = new ConnectionPool(endpoint);
        }

        public async Task<byte[]> GetAsync(string key, CacheCredential credential, CancellationToken ct = default)
        {
            var conn = await _pool.AcquireAsync(credential, ct);
            try
            {
                // Use conn.Credential (which may be the rebinded one)
                // to authorize the cache operation
                return await ExecuteGetAsync(conn, key, ct);
            }
            finally
            {
                _pool.Release(conn);
            }
        }

        private Task<byte[]> ExecuteGetAsync(PooledConnection conn, string key, CancellationToken ct)
        {
            // The session key from original auth is used for request signing
            // but authorization is checked against conn.Credential.Username
            return Task.FromResult(Encoding.UTF8.GetBytes($"value_for_{key}"));
        }
    }
}
